class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        cnt = 0  # num of bits 1
        while n > 0:
            if n & 1:
                cnt += 1
                if cnt > 1:
                    return False
            n >>= 1
        return cnt == 1

impl Solution {
  pub fn is_power_of_two(n: i32) -> bool {
    let mut cnt = 0; // num of bits 1
    let mut m = n;
    while m > 0 {
      if m & 1 == 1 {
        cnt += 1;
        if cnt > 1 {
          return false;
        }
      }
      m >>= 1;
    }
    cnt == 1
  }
}

